 write(o/'PUBLIC_COPY.md','\n'.join(lines)+'\n')
 abstract_read=subprocess.check_output(['/opt/homebrew/bin/pdftotext','-layout',str(asset_root/pdf),'-'],text=True);write(o/'published-reader.txt',abstract_read)
 write(o/'abstract-source.tex',abstract_tex+'\n')
 with (o/'RESEARCH_LOG.md').open('a') as f:f.write(now()+' — 65%: New source-bound configs and complete proposed public copy/sections/citation written. Original abstract and all custom authorities/receipt objects preserved. No rendering or publication claimed.\n')
